COMMENT ON TABLE observations_1h_legacy IS
    'Pre-computed 1h buckets imported from the Go weather_1h continuous
     aggregate, for the window where the raw readings behind them were deleted by
     the old 365-day retention policy before the migration. Not derived from
     observations and not rebuildable from anything. Never truncate this.';

-- The boundary. One row per station: the first bucket for which real raw exists.
-- Imports filter strictly below it and the assertion below proves the two sides do
-- not overlap, so the union views cannot double-count a bucket.
CREATE TABLE w9.legacy_boundary (
    station_id text PRIMARY KEY,
    cutover    timestamptz NOT NULL
);

COMMENT ON TABLE w9.legacy_boundary IS
    'Per station, the first bucket that has raw readings behind it. Set from the
     imported raw extent, not from the archive.';

CREATE PROCEDURE w9.set_legacy_boundary() LANGUAGE sql AS $fn$
    INSERT INTO w9.legacy_boundary (station_id, cutover)
    SELECT station_id, min(time) FROM observations GROUP BY 1
    ON CONFLICT (station_id) DO UPDATE SET cutover = excluded.cutover;
$fn$;

-- The 1d transform. One archived bucket becomes one legacy row.
--
-- The mean is the part worth reading twice. The old view stored a finished
-- average and the new level stores a sum and a count, so the import sets
-- count = 1 and sum = the average: mw_mean(avg, 1) = avg, exactly, with no
-- rounding and no reconstruction. The count is not a lie about how many
-- readings there were — nothing reads a count except the finaliser, nothing
-- rolls up out of the top level, and the alternative is inventing a reading
-- count the old view never recorded. docs/data-migration.md 4.2.
--
-- The same identity holds for the angle: atan2d(sind(d)/1, cosd(d)/1) = d.
CREATE PROCEDURE w9.import_legacy_1d() LANGUAGE plpgsql AS $fn$
BEGIN
    PERFORM w9.assert_archive_unique('1d');
    INSERT INTO observations_1d_legacy (bucket, station_id,
        barometer_sum,
        barometer_count,
        barometer_min,
        barometer_max,
        intemp_sum,
        intemp_count,
        intemp_min,
        intemp_max,
        inhumidity_sum,
        inhumidity_count,
        inhumidity_min,
        inhumidity_max,
        outtemp_sum,
