        extratemp1_min,
        extratemp1_max,
        rainrate_sum,
        rainrate_count,
        rainrate_max,
        rainincremental_total,
        dayrain_max,
        monthrain_max,
        yearrain_max,
        solarwatts_sum,
        solarwatts_count,
        potentialsolarwatts_sum,
        potentialsolarwatts_count,
        solarjoules_sum,
        solarjoules_count,
        uv_sum,
        uv_count,
        uv_min,
        uv_max,
        radiation_sum,
        radiation_count,
        radiation_min,
        radiation_max,
        consbatteryvoltage_sum,
        consbatteryvoltage_count,
        stationbatteryvoltage_sum,
        stationbatteryvoltage_count,
        snowdistance_sum,
        snowdistance_count,
        snowdepth_sum,
        snowdepth_count,
        extrafloat1_sum,
        extrafloat1_count,
        extrafloat1_min,
        extrafloat1_max,
        extrafloat2_sum,
        extrafloat2_count,
        extrafloat2_min,
        extrafloat2_max,
        extrafloat3_sum,
        extrafloat3_count,
        extrafloat3_min,
        extrafloat3_max,
        extrafloat4_sum,
        extrafloat4_count,
        extrafloat4_min,
        extrafloat4_max,
        extrafloat5_sum,
        extrafloat5_count,
        extrafloat5_min,
        extrafloat5_max,
        extrafloat6_sum,
        extrafloat6_count,
        extrafloat6_min,
        extrafloat6_max,
        extrafloat7_sum,
        extrafloat7_count,
        extrafloat7_min,
        extrafloat7_max,
        extrafloat8_sum,
        extrafloat8_count,
        extrafloat8_min,
        extrafloat8_max,
        extrafloat9_sum,
        extrafloat9_count,
        extrafloat9_min,
        extrafloat9_max,
        extrafloat10_sum,
        extrafloat10_count,
        extrafloat10_min,
        extrafloat10_max,
        temp1_sum,
        temp1_count,
        temp1_min,
        temp1_max,
        temp2_sum,
        temp2_count,
