        a.min_aqi_pm25_in_24h,
        a.max_aqi_pm25_in_24h,
        a.lightning_distance
    FROM w9.weather_1d_archive a
    JOIN w9.station_map m ON m.stationname = a.stationname
    LEFT JOIN w9.legacy_boundary b ON b.station_id = m.station_id
   WHERE b.cutover IS NULL OR a.bucket < b.cutover
   ON CONFLICT (station_id, bucket) DO NOTHING;
END $fn$;

-- The 1h transform. One archived bucket becomes one legacy row.
--
-- The mean is the part worth reading twice. The old view stored a finished
-- average and the new level stores a sum and a count, so the import sets
-- count = 1 and sum = the average: mw_mean(avg, 1) = avg, exactly, with no
-- rounding and no reconstruction. The count is not a lie about how many
-- readings there were — nothing reads a count except the finaliser, nothing
-- rolls up out of the top level, and the alternative is inventing a reading
-- count the old view never recorded. docs/data-migration.md 4.2.
--
-- The same identity holds for the angle: atan2d(sind(d)/1, cosd(d)/1) = d.
CREATE PROCEDURE w9.import_legacy_1h() LANGUAGE plpgsql AS $fn$
BEGIN
    PERFORM w9.assert_archive_unique('1h');
    INSERT INTO observations_1h_legacy (bucket, station_id,
        barometer_sum,
        barometer_count,
        barometer_min,
