    JOIN w9.station_map m ON m.stationname = a.stationname
    LEFT JOIN w9.legacy_boundary b ON b.station_id = m.station_id
   WHERE b.cutover IS NULL OR a.bucket < b.cutover
   ON CONFLICT (station_id, bucket) DO NOTHING;
END $fn$;

-- The read-side union. /span reads these where it would read the level, for the
-- one reason the legacy table exists: below the cutover the level is empty and the
-- archive is all there is. UNION ALL and not UNION, because the assertion below
-- establishes disjointness and a UNION would pay for a de-duplication that cannot
-- find anything.
--
-- Only the 1-day level needs this. /span reads observations_1h over at most 14
-- days and observations_5m over at most 48 hours (W4 1.2), both of which are
-- inside the raw window on any day this migration could run; observations_1d is
-- the only level /span reads over history. observations_1h_legacy is imported
-- anyway, because it is 40 MB and because it is the only hourly resolution that
-- window will ever have.

