-- Disjointness, asserted rather than assumed. An overlapping bucket would make
-- /span return two elements with the same `ts`, which no client expects and which
-- the frozen contract's "a gap is missing elements" rule (Q-9) does not cover.
CREATE FUNCTION w9.assert_legacy_disjoint(level text) RETURNS void
LANGUAGE plpgsql AS $fn$
DECLARE n bigint;
BEGIN
    EXECUTE format('SELECT count(*) FROM observations_%s l
                    JOIN observations_%s_legacy g USING (station_id, bucket)',
                   level, level)
      INTO n;
    IF n > 0 THEN
        RAISE EXCEPTION 'observations_% and observations_%_legacy share % buckets',
            level, level, n;
    END IF;
END $fn$;

